CREATE TABLE users (id TEXT PRIMARY KEY, ai_connect_username TEXT NOT NULL UNIQUE, username TEXT NOT NULL, email TEXT, role TEXT NOT NULL DEFAULT 'CREATOR', status TEXT NOT NULL DEFAULT 'ACTIVE', quota_balance NUMERIC NOT NULL DEFAULT 0, last_login_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', story_environment TEXT NOT NULL DEFAULT '', genres_json TEXT NOT NULL DEFAULT '[]', drama_type TEXT NOT NULL DEFAULT '动态漫', art_style TEXT NOT NULL DEFAULT '半写实国漫', episode_count INTEGER NOT NULL DEFAULT 10, episode_duration_sec INTEGER NOT NULL DEFAULT 90, cover_asset_id TEXT, settings_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX idx_projects_owner ON projects(owner_user_id, deleted_at, updated_at);
CREATE TABLE workflows (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', canvas_json TEXT NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 0, latest_version_no INTEGER NOT NULL DEFAULT 0, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE workflow_versions (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), version_no INTEGER NOT NULL, snapshot_json TEXT NOT NULL, checksum TEXT NOT NULL, published_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(workflow_id, version_no));
CREATE TABLE nodes (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE, node_type TEXT NOT NULL, name TEXT NOT NULL, template_version_id TEXT, config_json TEXT NOT NULL DEFAULT '{}', position_x NUMERIC NOT NULL, position_y NUMERIC NOT NULL, width NUMERIC, height NUMERIC, group_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_nodes_workflow ON nodes(workflow_id);
CREATE TABLE edges (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE, source_node_id TEXT NOT NULL, source_port TEXT NOT NULL, target_node_id TEXT NOT NULL, target_port TEXT NOT NULL, mapping_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(workflow_id, source_node_id, source_port, target_node_id, target_port));
CREATE TABLE workflow_runs (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), workflow_version_id TEXT NOT NULL REFERENCES workflow_versions(id), project_id TEXT NOT NULL REFERENCES projects(id), trigger_type TEXT NOT NULL, target_node_ids_json TEXT, status TEXT NOT NULL, progress NUMERIC NOT NULL DEFAULT 0, input_snapshot_json TEXT NOT NULL DEFAULT '{}', estimated_cost NUMERIC NOT NULL DEFAULT 0, actual_cost NUMERIC NOT NULL DEFAULT 0, started_at TEXT, finished_at TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_runs_project_status ON workflow_runs(project_id, status, created_at);
CREATE TABLE node_runs (id TEXT PRIMARY KEY, workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id), node_id TEXT NOT NULL, node_type TEXT NOT NULL, status TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, progress NUMERIC NOT NULL DEFAULT 0, input_asset_ids_json TEXT NOT NULL DEFAULT '[]', input_fingerprint TEXT, config_snapshot_json TEXT NOT NULL DEFAULT '{}', template_snapshot_json TEXT, resolved_variables_json TEXT, rendered_prompt TEXT, rendered_negative_prompt TEXT, provider TEXT, model TEXT, external_task_id TEXT, idempotency_key TEXT NOT NULL UNIQUE, error_code TEXT, error_message TEXT, started_at TEXT, finished_at TEXT, next_retry_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_node_runs_run ON node_runs(workflow_run_id, status);
CREATE TABLE assets (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), logical_key TEXT NOT NULL, version_no INTEGER NOT NULL, parent_asset_id TEXT REFERENCES assets(id), asset_type TEXT NOT NULL, name TEXT NOT NULL, content_status TEXT NOT NULL DEFAULT 'draft', is_selected INTEGER NOT NULL DEFAULT 0, is_locked INTEGER NOT NULL DEFAULT 0, content_text TEXT, storage_key TEXT, thumbnail_key TEXT, mime_type TEXT NOT NULL DEFAULT 'application/json', size_bytes INTEGER, sha256 TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', node_run_id TEXT REFERENCES node_runs(id), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(project_id, logical_key, version_no));
CREATE INDEX idx_assets_project_type ON assets(project_id, asset_type, content_status, deleted_at);
CREATE UNIQUE INDEX uq_asset_selected ON assets(project_id, logical_key) WHERE is_selected = 1 AND deleted_at IS NULL;
CREATE TABLE asset_relations (id TEXT PRIMARY KEY, from_asset_id TEXT NOT NULL REFERENCES assets(id), to_asset_id TEXT NOT NULL REFERENCES assets(id), relation_type TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE templates (id TEXT PRIMARY KEY, owner_user_id TEXT REFERENCES users(id), node_type TEXT NOT NULL, name TEXT NOT NULL, scope TEXT NOT NULL, status TEXT NOT NULL, latest_version_no INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE template_versions (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES templates(id), version TEXT NOT NULL, status TEXT NOT NULL, schema_version TEXT NOT NULL, definition_json TEXT NOT NULL, checksum TEXT NOT NULL, change_log TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL, published_at TEXT, UNIQUE(template_id, version));
CREATE TABLE node_run_logs (id TEXT PRIMARY KEY, node_run_id TEXT NOT NULL REFERENCES node_runs(id), seq INTEGER NOT NULL, level TEXT NOT NULL, message TEXT NOT NULL, details_json TEXT, created_at TEXT NOT NULL, UNIQUE(node_run_id, seq));
CREATE TABLE run_events (id TEXT PRIMARY KEY, event_id INTEGER NOT NULL, workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id), event_type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workflow_run_id, event_id));
CREATE TABLE provider_configs (id TEXT PRIMARY KEY, name TEXT NOT NULL, capability TEXT NOT NULL, encrypted_secret TEXT, base_url TEXT, status TEXT NOT NULL, config_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE model_configs (id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES provider_configs(id), model_code TEXT NOT NULL, capability TEXT NOT NULL, limits_json TEXT NOT NULL DEFAULT '{}', pricing_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(provider_id, model_code));
CREATE TABLE usage_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), run_id TEXT REFERENCES workflow_runs(id), node_run_id TEXT REFERENCES node_runs(id), provider TEXT, model TEXT, quantity NUMERIC NOT NULL DEFAULT 0, cost NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, before_json TEXT, after_json TEXT, ip TEXT, created_at TEXT NOT NULL);
CREATE TABLE refresh_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
